// HTTP Request returns text so malformed JSON retains its HTTP status.
function normalize(raw, kind) {
  const readiness = kind === 'readiness';
  const result = {
    status: 'unknown', http_status: null, request_id: null, error_code: null,
  };
  if (readiness) result.checks = { application: 'unknown', database: 'unknown' };
  function fail(code) {
    result.error_code = code;
    return result;
  }

  if (raw === null) return fail('CONFIGURATION_ERROR');
  if (raw.error) {
    const error = raw.error;
    const hint = [error.code, error.cause?.code, error.message, error.description,
      raw.details?.errorCode, typeof error === 'string' ? error : ''].join(' ');
    if (/timed?\s*out|timeout|ETIMEDOUT|ECONNABORTED/i.test(hint)) return fail('TIMEOUT');
    if (/ECONNREFUSED|ECONNRESET|ENOTFOUND|EAI_AGAIN|ENETUNREACH|EHOSTUNREACH|socket hang up|connect|dns|offline/i.test(hint)) {
      if (!readiness) result.status = 'unavailable';
      return fail('NETWORK_ERROR');
    }
    // A new integration/programming error must be visible in execution history.
    throw new Error('Unrecognized HTTP Request failure');
  }

  if (!Number.isInteger(raw.statusCode)) throw new Error('Missing HTTP node status');
  result.http_status = raw.statusCode;
  const header = (name) => Object.entries(raw.headers ?? {})
    .find(([key]) => key.toLowerCase() === name)?.[1];
  const identifier = header('x-request-id');
  if (typeof identifier === 'string' && /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(identifier)) {
    result.request_id = identifier;
  }
  if (raw.statusCode !== 200 && !(readiness && raw.statusCode === 503)) return fail('HTTP_ERROR');
  if (String(header('content-type')).split(';')[0].trim().toLowerCase() !== 'application/json') return fail('INVALID_RESPONSE');
  let body;
  try { body = JSON.parse(raw.body); } catch { return fail('INVALID_RESPONSE'); }
  if (!readiness) {
    if (body?.status !== 'ok' || body.service !== 'dealmind-api') return fail('INVALID_RESPONSE');
    result.status = 'operational';
    return result;
  }

  const app = body?.checks?.application;
  const db = body?.checks?.database;
  if (raw.statusCode === 200 && body?.status === 'ready' && app === 'ok' && db === 'ok') {
    result.status = 'operational';
    result.checks = { application: app, database: db };
    return result;
  }
  if (raw.statusCode === 503 && body?.status === 'not_ready' && db === 'not_ready' && ['ok','not_ready'].includes(app)) {
    result.status = 'degraded';
    result.checks = { application: app, database: app === 'ok' ? db : 'unknown' };
    return fail(app === 'ok' ? 'DATABASE_NOT_READY' : 'APPLICATION_NOT_READY');
  }
  return fail('INVALID_RESPONSE');
}

function probe(name) {
  if (!$(name).isExecuted) return null;
  const items = $(name).all();
  if (items.length !== 1) throw new Error('Expected one HTTP result');
  return items[0].json;
}
return [{ json: {
  health: normalize(probe('Check API Health'), 'health'),
  ready: normalize(probe('Check API Readiness'), 'readiness'),
} }];

const context = $('Initialize Context').first().json;
const { health, ready } = $input.first().json;
const transportFailed = probe => ['NETWORK_ERROR','TIMEOUT'].includes(probe.error_code);
const readinessKnown = ['operational','degraded'].includes(ready.status);
let overall = 'unknown';
if (health.status === 'operational' && ready.status === 'operational') overall = 'operational';
else if (health.status === 'operational' || readinessKnown) overall = 'degraded';
else if (transportFailed(health) && transportFailed(ready)) overall = 'unavailable';

const messages = {
  NETWORK_ERROR: 'Could not connect to the API', TIMEOUT: 'API request timed out',
  HTTP_ERROR: 'Unexpected HTTP status', INVALID_RESPONSE: 'Response did not match the API contract',
  DATABASE_NOT_READY: 'Database readiness check failed', APPLICATION_NOT_READY: 'Application lifecycle is not ready',
  CONFIGURATION_ERROR: 'Invalid API origin',
};
const errors = [];
for (const [source, probe] of [['health', health], ['readiness', ready]]) {
  if (probe.error_code) errors.push({ code: probe.error_code, message: messages[probe.error_code], source });
}
const endpoint = ({ status, http_status, request_id }) => ({ status, http_status, request_id });
const backend = endpoint(health);
if (health.status !== 'operational') {
  if (readinessKnown) backend.status = 'degraded';
  else backend.status = overall === 'unavailable' ? 'unavailable' : 'unknown';
}
const finished = new Date();
return [{ json: {
  schema_version: '1.0', workflow: context.workflow, workflow_version: context.workflow_version,
  execution_id: context.execution_id, started_at: context.started_at, finished_at: finished.toISOString(),
  duration_ms: Math.max(0, finished.getTime() - Date.parse(context.started_at)), overall_status: overall,
  services: { backend, readiness: endpoint(ready),
    database: { status: ready.checks.database === 'ok' ? 'operational' : ready.checks.database } },
  errors,
} }];
